"""Bounded character-prefix-aware DataFrame column permutation search."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorder rows and columns while preserving all source values."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the latest public row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return an exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Score a row-string multiset by sorted-adjacent character LCP reuse."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their source positions."""
        result = {}
        for i, name in enumerate(columns):
            result.setdefault(str(name), []).append(i)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build deterministic union-find blocks from requested merge pairs."""
        parent = list(range(width))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(g) for g in groups.values()), key=lambda g: g[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Return a preferred topological order respecting dependencies and blocks."""
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for a, b in zip(block, block[1:]):
                add(a, b)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for a, b in edges:
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {value: i for i, value in enumerate(preference)}
        heap = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(heap)

        answer = []
        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))

        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted repetition statistics for each column."""
        rows, width = text.shape
        result = []
        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @staticmethod
    def _affinity(text, left, right):
        """Estimate directed repeated-value affinity between two columns."""
        groups = {}
        for row in range(text.shape[0]):
            groups.setdefault(text[row, left], []).append(row)

        score = 0
        for members in groups.values():
            if len(members) < 2:
                continue
            counts = {}
            for row in members:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                score += len(value) * count * (count - 1)
        return score

    @classmethod
    def _beam_orders(cls, text, stats, blocks):
        """Generate two bounded block-level candidate preferences."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [
            sum(stats[col][0] for col in block)
            for block in blocks
        ]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:24]
        representatives = [block[:2] for block in blocks]

        affinity = {}
        for a in active:
            for b in active:
                if a != b:
                    affinity[a, b] = sum(
                        cls._affinity(text, x, y)
                        for x in representatives[a]
                        for y in representatives[b]
                    )

        beam = [((seed,), frozenset(active) - {seed}, 0) for seed in active]
        for _ in range(max(0, len(active) - 1)):
            expanded = []
            for path, remaining, value in beam:
                if not remaining:
                    expanded.append((path, remaining, value))
                    continue
                last = path[-1]
                for nxt in remaining:
                    expanded.append((
                        path + (nxt,),
                        remaining - {nxt},
                        value + affinity.get((last, nxt), 0),
                    ))
            expanded.sort(key=lambda item: (-item[2], item[0]))
            beam = expanded[:4]

        answers, seen = [], set()
        for path, _, _ in sorted(beam, key=lambda item: (-item[2], item[0])):
            tail = sorted(
                (i for i in range(len(blocks)) if i not in path),
                key=lambda i: (-mass[i], blocks[i][0]),
            )
            flat = tuple(
                col
                for block_id in tuple(path) + tuple(tail)
                for col in blocks[block_id]
            )
            if flat not in seen:
                seen.add(flat)
                answers.append(list(flat))
            if len(answers) == 2:
                break
        return answers or [sum(blocks, [])]

    @staticmethod
    def _serialize(text, order):
        """Serialize every source row under one column permutation."""
        return [
            "".join(text[row, col] for col in order)
            for row in range(text.shape[0])
        ]

    @classmethod
    def _block_sequence(cls, order, blocks):
        """Return the block sequence represented by an order, if valid."""
        owner = {}
        for block_id, block in enumerate(blocks):
            for col in block:
                owner[col] = block_id

        sequence = []
        for col in order:
            block_id = owner[col]
            if not sequence or sequence[-1] != block_id:
                sequence.append(block_id)
        return sequence if len(sequence) == len(blocks) else None

    @classmethod
    def _two_opt(cls, text, columns, dependencies, blocks,
                 incumbent, serialized, score):
        """Test at most twelve deterministic contiguous block-segment reversals."""
        if len(blocks) > 24:
            return incumbent, serialized, score

        total_mass = sum(len(value) for value in text.flat)
        if total_mass > 2_000_000:
            return incumbent, serialized, score

        sequence = cls._block_sequence(incumbent, blocks)
        if sequence is None or len(sequence) < 2:
            return incumbent, serialized, score

        locations = {block_id: i for i, block_id in enumerate(sequence)}
        block_mass = [
            sum(
                len(text[row, col])
                for row in range(text.shape[0])
                for col in block
            )
            for block in blocks
        ]
        important = sorted(
            range(len(blocks)),
            key=lambda i: (-block_mass[i], i),
        )[:6]

        intervals = set()
        for block_id in important:
            center = locations.get(block_id)
            if center is None:
                continue
            for left in (center - 1, center):
                for right in (center, center + 1):
                    if 0 <= left < right < len(sequence):
                        intervals.add((left, right))

        intervals = sorted(
            intervals,
            key=lambda pair: (pair[1] - pair[0], pair[0], pair[1]),
        )[:12]

        best_order = list(incumbent)
        best_serialized = serialized
        best_score = score

        for left, right in intervals:
            target = (
                sequence[:left]
                + list(reversed(sequence[left:right + 1]))
                + sequence[right + 1:]
            )
            preference = [
                col for block_id in target for col in blocks[block_id]
            ]
            repaired = cls._repair(
                len(columns), preference, columns, dependencies, blocks
            )
            if cls._block_sequence(repaired, blocks) != target:
                continue

            candidate_serialized = cls._serialize(text, repaired)
            candidate_score = cls._score(candidate_serialized)
            if candidate_score > best_score:
                best_order = repaired
                best_serialized = candidate_serialized
                best_score = candidate_score

        return best_order, best_serialized, best_score

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized text and permute source values unchanged."""
        row_order = sorted(
            range(len(serialized)),
            key=lambda r: (serialized[r], r),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for out_row, src_row in enumerate(row_order):
            values[out_row, :] = [source[src_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Select the best bounded candidate, refine it with block 2-opt, and materialize it."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._beam_orders(text, stats, blocks))
        preferences = preferences[:3]

        best_score = -1
        best_order = None
        best_serialized = None

        for preference in preferences:
            order = self._repair(
                width, preference, columns, one_way_dep, blocks
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        best_order, best_serialized, best_score = self._two_opt(
            text,
            columns,
            one_way_dep,
            blocks,
            best_order,
            best_serialized,
            best_score,
        )

        result, public_orders = self._materialize(
            df, source, best_order, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

